sys_script_fix.script:
(function() {

    var INSPECTION_TABLE = 'x_1947064_autoca_0_inspection';
    var APPOINTMENT_TABLE = 'x_1947064_autoca_0_appointment';
    var VEHICLE_TABLE = 'x_1947064_autoca_0_vehicle';
    var RECOMMENDATION_TABLE = 'x_1947064_autoca_0_reccommendation';

    var total = 0;
    var appointmentUpdated = 0;
    var vehicleUpdated = 0;
    var technicianUpdated = 0;
    var recommendationUpdated = 0;

    var appointmentUnmatched = 0;
    var vehicleUnmatched = 0;
    var technicianUnmatched = 0;
    var recommendationUnmatched = 0;


    // --------------------------------------------------
    // Generic function:
    // Find a record by sys_id OR display value
    // --------------------------------------------------
    function findRecord(tableName, sourceValue) {

        if (!sourceValue)
            return null;

        sourceValue = (sourceValue + '').trim();

        var gr = new GlideRecord(tableName);

        // First try sys_id
        if (gr.get(sourceValue))
            return gr;

        // Otherwise compare display values
        gr = new GlideRecord(tableName);
        gr.query();

        while (gr.next()) {

            var displayValue = gr.getDisplayValue();

            if (displayValue &&
                displayValue.toLowerCase() == sourceValue.toLowerCase()) {

                return gr;
            }
        }

        return null;
    }


    // --------------------------------------------------
    // Technician → real sys_user
    // --------------------------------------------------
    function findUser(sourceValue) {

        if (!sourceValue)
            return null;

        sourceValue = (sourceValue + '').trim();

        var user = new GlideRecord('sys_user');

        // Try sys_id
        if (user.get(sourceValue))
            return user;

        // Try name
        user = new GlideRecord('sys_user');
        user.addQuery('name', sourceValue);
        user.setLimit(1);
        user.query();

        if (user.next())
            return user;

        // Try user_name
        user = new GlideRecord('sys_user');
        user.addQuery('user_name', sourceValue);
        user.setLimit(1);
        user.query();

        if (user.next())
            return user;

        return null;
    }


    gs.info('========== INSPECTION REFERENCE PREPARATION ==========');


    var inspection = new GlideRecord(INSPECTION_TABLE);
    inspection.query();

    while (inspection.next()) {

        total++;

        // ----------------------------------------------
        // 1. APPOINTMENT
        // ----------------------------------------------
        if (!inspection.getValue('appointment_ref') &&
            inspection.getValue('appointment')) {

            var appointment = findRecord(
                APPOINTMENT_TABLE,
                inspection.getValue('appointment')
            );

            if (appointment) {
                inspection.setValue(
                    'appointment_ref',
                    appointment.getUniqueValue()
                );
                appointmentUpdated++;
            } else {
                appointmentUnmatched++;
                gs.info(
                    'APPOINTMENT NOT FOUND: ' +
                    inspection.getValue('appointment')
                );
            }
        }


        // ----------------------------------------------
        // 2. VEHICLE
        // ----------------------------------------------
        if (!inspection.getValue('vehicle_ref') &&
            inspection.getValue('vehicle')) {

            var vehicle = findRecord(
                VEHICLE_TABLE,
                inspection.getValue('vehicle')
            );

            if (vehicle) {
                inspection.setValue(
                    'vehicle_ref',
                    vehicle.getUniqueValue()
                );
                vehicleUpdated++;
            } else {
                vehicleUnmatched++;
                gs.info(
                    'VEHICLE NOT FOUND: ' +
                    inspection.getValue('vehicle')
                );
            }
        }


        // ----------------------------------------------
        // 3. TECHNICIAN
        // ----------------------------------------------
        if (!inspection.getValue('technician_ref') &&
            inspection.getValue('technician')) {

            var technician = findUser(
                inspection.getValue('technician')
            );

            if (technician) {
                inspection.setValue(
                    'technician_ref',
                    technician.getUniqueValue()
                );
                technicianUpdated++;
            } else {
                technicianUnmatched++;
                gs.info(
                    'TECHNICIAN NOT FOUND: ' +
                    inspection.getValue('technician')
                );
            }
        }


        // ----------------------------------------------
        // 4. RECOMMENDATION
        // ----------------------------------------------
        if (!inspection.getValue('recommendation_ref') &&
            inspection.getValue('recommendation')) {

            var recommendation = findRecord(
                RECOMMENDATION_TABLE,
                inspection.getValue('recommendation')
            );

            if (recommendation) {
                inspection.setValue(
                    'recommendation_ref',
                    recommendation.getUniqueValue()
                );
                recommendationUpdated++;
            } else {
                recommendationUnmatched++;
                gs.info(
                    'RECOMMENDATION NOT FOUND: ' +
                    inspection.getValue('recommendation')
                );
            }
        }


        // Save the inspection
        inspection.update();
    }


    gs.info('========== INSPECTION REFERENCE RESULT ==========');
    gs.info('TOTAL INSPECTIONS = ' + total);

    gs.info('APPOINTMENT UPDATED = ' + appointmentUpdated);
    gs.info('VEHICLE UPDATED = ' + vehicleUpdated);
    gs.info('TECHNICIAN UPDATED = ' + technicianUpdated);
    gs.info('RECOMMENDATION UPDATED = ' + recommendationUpdated);

    gs.info('APPOINTMENT UNMATCHED = ' + appointmentUnmatched);
    gs.info('VEHICLE UNMATCHED = ' + vehicleUnmatched);
    gs.info('TECHNICIAN UNMATCHED = ' + technicianUnmatched);
    gs.info('RECOMMENDATION UNMATCHED = ' + recommendationUnmatched);

    gs.info('=================================================');

})();
